package com.collegeerp.erp.fee.controller; import com.collegeerp.erp.common.api.ApiResponse; import com.collegeerp.erp.common.dto.PageResponse; import com.collegeerp.erp.fee.dto.*; import com.collegeerp.erp.fee.enums.*; import com.collegeerp.erp.fee.service.FeeService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/super-admin/fee-structures") public class SuperAdminFeeStructureController{private final FeeService service;public SuperAdminFeeStructureController(FeeService s){service=s;}@PostMapping public ApiResponse<?>create(@Valid@RequestBody CreateFeeStructureRequest r){return ApiResponse.success("Fee structure created",service.createStructure(r));}@GetMapping("/search")public ApiResponse<PageResponse<FeeStructureResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String academicYear,@RequestParam(required=false)StudentCategory studentCategory,@RequestParam(required=false)FeeStructureStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Fee structures",service.searchStructures(keyword,collegeId,departmentId,academicYear,studentCategory,status,page,size,"createdAt","desc"));}@GetMapping("/{id}")public ApiResponse<?>get(@PathVariable Long id){return ApiResponse.success("Fee structure",service.getStructure(id));}@PutMapping("/{id}")public ApiResponse<?>update(@PathVariable Long id,@Valid@RequestBody UpdateFeeStructureRequest r){return ApiResponse.success("Fee structure updated",service.updateStructure(id,r));}@DeleteMapping("/{id}")public ApiResponse<?>delete(@PathVariable Long id){service.deleteStructure(id);return ApiResponse.success("Fee structure deleted",null);}@PatchMapping("/{id}/{action:activate|deactivate}")public ApiResponse<?>status(@PathVariable Long id,@PathVariable String action){return ApiResponse.success("Fee structure status updated",service.setStructureStatus(id,action.equals("activate")?FeeStructureStatus.ACTIVE:FeeStructureStatus.INACTIVE));}}
